\set ON_ERROR_STOP on
BEGIN READ ONLY;
SET LOCAL search_path = pg_catalog, public;
DO $verify$
DECLARE t jsonb; c jsonb; x jsonb; a record; rel oid; actual_default text; equal_default boolean; keys text[];
BEGIN
FOR t IN SELECT value FROM jsonb_array_elements('[{"database":"WEBFUSION","name":"USERS","columns":[{"name":"ID_USER","position":1,"source_type":"bigint(20)","source_definition":"`ID_USER` bigint(20) NOT NULL AUTO_INCREMENT","type":"bigint","nullable":false,"default":null,"generated":true,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql","sequence":"USERS__ID_USER__seq"},{"name":"NA_USER_NAME","position":2,"source_type":"varchar(255)","source_definition":"`NA_USER_NAME` varchar(255) DEFAULT NULL","type":"character varying(255)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_USER_EMAIL","position":3,"source_type":"varchar(320)","source_definition":"`NA_USER_EMAIL` varchar(320) NOT NULL","type":"character varying(320)","nullable":false,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_JOB_TITLE","position":4,"source_type":"varchar(255)","source_definition":"`NA_JOB_TITLE` varchar(255) DEFAULT NULL","type":"character varying(255)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_DEPARTMENT","position":5,"source_type":"varchar(255)","source_definition":"`NA_DEPARTMENT` varchar(255) DEFAULT NULL","type":"character varying(255)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_LOCATION","position":6,"source_type":"varchar(255)","source_definition":"`NA_LOCATION` varchar(255) DEFAULT NULL","type":"character varying(255)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_URL_PROFILE_IMG","position":7,"source_type":"varchar(2048)","source_definition":"`NA_URL_PROFILE_IMG` varchar(2048) DEFAULT NULL","type":"character varying(2048)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"DT_CREATED_AT","position":8,"source_type":"datetime","source_definition":"`DT_CREATED_AT` datetime NOT NULL DEFAULT current_timestamp()","type":"timestamp(0) without time zone","nullable":false,"default":"date_trunc(''second'', statement_timestamp() AT TIME ZONE ''UTC'')","generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"DT_UPDATED_AT","position":9,"source_type":"datetime","source_definition":"`DT_UPDATED_AT` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()","type":"timestamp(0) without time zone","nullable":false,"default":"date_trunc(''second'', statement_timestamp() AT TIME ZONE ''UTC'')","generated":false,"on_update":true,"collation":null,"test":"test_structure.sql; test_rules.sql"}],"primary_key":["ID_USER"],"unique":[{"name":"UQ_USERS_USER_EMAIL","physical":"USERS__UQ_USERS_USER_EMAIL","members":[{"column":"NA_USER_EMAIL","prefix":null,"descending":false}],"kind":"btree","mechanism":"unique"}],"indexes":[],"foreign_keys":[]},{"database":"WEBFUSION","name":"USER_ROLES","columns":[{"name":"ID_USER","position":1,"source_type":"bigint(20)","source_definition":"`ID_USER` bigint(20) NOT NULL","type":"bigint","nullable":false,"default":null,"generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"NA_ROLE","position":2,"source_type":"enum(''admin'',''developer'')","source_definition":"`NA_ROLE` enum(''admin'',''developer'') NOT NULL","type":"character varying(9)","nullable":false,"default":null,"generated":false,"on_update":false,"collation":"unicode_ci","test":"test_structure.sql; test_rules.sql"},{"name":"IS_ACTIVE","position":3,"source_type":"tinyint(1)","source_definition":"`IS_ACTIVE` tinyint(1) NOT NULL DEFAULT 1","type":"smallint","nullable":false,"default":"1","generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"DT_CREATED_AT","position":4,"source_type":"datetime","source_definition":"`DT_CREATED_AT` datetime NOT NULL DEFAULT current_timestamp()","type":"timestamp(0) without time zone","nullable":false,"default":"date_trunc(''second'', statement_timestamp() AT TIME ZONE ''UTC'')","generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"DT_UPDATED_AT","position":5,"source_type":"datetime","source_definition":"`DT_UPDATED_AT` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()","type":"timestamp(0) without time zone","nullable":false,"default":"date_trunc(''second'', statement_timestamp() AT TIME ZONE ''UTC'')","generated":false,"on_update":true,"collation":null,"test":"test_structure.sql; test_rules.sql"}],"primary_key":["ID_USER","NA_ROLE"],"unique":[],"indexes":[{"name":"IX_USER_ROLES_ROLE_ACTIVE","physical":"USER_ROLES__IX_USER_ROLES_ROLE_ACTIVE","members":[{"column":"NA_ROLE","prefix":null,"descending":false},{"column":"IS_ACTIVE","prefix":null,"descending":false}],"kind":"btree","expression":"\"NA_ROLE\" NULLS FIRST, \"IS_ACTIVE\" NULLS FIRST"}],"foreign_keys":[{"name":"FK_USER_ROLES_USER","columns":["ID_USER"],"table":"USERS","references":["ID_USER"],"delete":"CASCADE","update":"NO ACTION"}]}]'::jsonb) LOOP
rel := to_regclass(format('%I.%I', 'WEBFUSION', t->>'name'));
IF rel IS NULL THEN RAISE EXCEPTION 'Missing table %', t->>'name'; END IF;
IF (SELECT relkind FROM pg_class WHERE oid=rel) <> 'r' THEN RAISE EXCEPTION 'Not a base table %', t->>'name'; END IF;
IF (SELECT count(*) FROM pg_attribute WHERE attrelid=rel AND attnum>0 AND NOT attisdropped) <> jsonb_array_length(t->'columns') THEN RAISE EXCEPTION 'Column count %', t->>'name'; END IF;
FOR c IN SELECT value FROM jsonb_array_elements(t->'columns') LOOP
SELECT at.*, format_type(at.atttypid, at.atttypmod) typ, co.collname, co.collprovider, co.collisdeterministic, co.colllocale, pg_get_expr(d.adbin,d.adrelid) def INTO a FROM pg_attribute at LEFT JOIN pg_attrdef d ON d.adrelid=at.attrelid AND d.adnum=at.attnum LEFT JOIN pg_collation co ON co.oid=at.attcollation WHERE at.attrelid=rel AND at.attname=c->>'name';
IF NOT FOUND OR a.attnum <> (c->>'position')::int OR a.typ <> replace(c->>'type','public.','') OR a.attnotnull = (c->>'nullable')::boolean THEN RAISE EXCEPTION 'Column attributes %.% expected %, observed %', t->>'name',c->>'name',c,row_to_json(a); END IF;
IF c->>'collation' IS NOT NULL AND a.collname IS DISTINCT FROM c->>'collation' THEN RAISE EXCEPTION 'Collation %.%',t->>'name',c->>'name'; END IF;
IF c->>'collation' IS NOT NULL AND (a.collprovider<>'i' OR a.collisdeterministic OR a.colllocale<>'und-u-ks-level1') THEN RAISE EXCEPTION 'ICU profile %.%',t->>'name',c->>'name'; END IF;
actual_default := a.def;
IF (c->>'default' IS NULL) <> (actual_default IS NULL) THEN RAISE EXCEPTION 'Default presence %.%',t->>'name',c->>'name'; END IF;
IF actual_default IS NOT NULL THEN EXECUTE format('SELECT ((%s)::%s)::text COLLATE "C" IS NOT DISTINCT FROM ((%s)::%s)::text COLLATE "C"',actual_default,c->>'type',c->>'default',c->>'type') INTO equal_default; IF NOT equal_default THEN RAISE EXCEPTION 'Default %.%',t->>'name',c->>'name'; END IF; END IF;
IF (c->>'generated')::boolean AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='a00_allocate' AND tgenabled='O' AND tgtype=23 AND tgfoid='rffusion_support.allocate_id()'::regprocedure AND tgnargs=3 AND tgargs=convert_to(c->>'name','UTF8')||decode('00','hex')||convert_to('WEBFUSION','UTF8')||decode('00','hex')||convert_to(c->>'sequence','UTF8')||decode('00','hex') AND ARRAY(SELECT unnest(tgattr))=ARRAY[a.attnum]) THEN RAISE EXCEPTION 'ID trigger binding %',t->>'name'; END IF;
IF (c->>'generated')::boolean AND NOT EXISTS (SELECT 1 FROM pg_sequence s JOIN pg_class sq ON sq.oid=s.seqrelid JOIN pg_namespace ns ON ns.oid=sq.relnamespace JOIN pg_depend d ON d.objid=sq.oid AND d.refobjid=rel AND d.refobjsubid=a.attnum AND d.deptype='a' WHERE ns.nspname='WEBFUSION' AND sq.relname=c->>'sequence' AND s.seqincrement=1 AND NOT s.seqcycle AND s.seqmin=1 AND s.seqmax=CASE WHEN c->>'type'='bigint' THEN 9223372036854775807::bigint ELSE 2147483647 END) THEN RAISE EXCEPTION 'Sequence attributes %.%',t->>'name',c->>'name'; END IF;
IF (c->>'on_update')::boolean AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='z90_updated' AND tgenabled='O' AND tgtype=19 AND tgfoid='rffusion_support.update_timestamp()'::regprocedure AND tgnargs=1 AND tgargs=convert_to(c->>'name','UTF8')||decode('00','hex')) THEN RAISE EXCEPTION 'Timestamp trigger binding %',t->>'name'; END IF;
END LOOP;
IF (SELECT count(*) FROM pg_constraint WHERE conrelid=rel AND contype='f')<>jsonb_array_length(t->'foreign_keys') THEN RAISE EXCEPTION 'Unexpected FK %',t->>'name'; END IF;
IF (SELECT count(*) FROM pg_constraint WHERE conrelid=rel AND contype='u')<>(SELECT count(*) FROM jsonb_array_elements(t->'unique') u WHERE u->>'mechanism'='unique') THEN RAISE EXCEPTION 'Unexpected unique constraint %',t->>'name'; END IF;
IF (SELECT count(*) FROM pg_index WHERE indrelid=rel)<>1+jsonb_array_length(t->'indexes')+(SELECT count(*) FROM jsonb_array_elements(t->'unique') u WHERE u->>'mechanism'='unique') THEN RAISE EXCEPTION 'Unexpected/missing index %',t->>'name'; END IF;
SELECT array_agg(at.attname::text ORDER BY k.ordinality) INTO keys FROM pg_constraint p CROSS JOIN LATERAL unnest(p.conkey) WITH ORDINALITY k(num,ordinality) JOIN pg_attribute at ON at.attrelid=p.conrelid AND at.attnum=k.num WHERE p.conrelid=rel AND p.contype='p';
IF to_jsonb(keys) IS DISTINCT FROM t->'primary_key' THEN RAISE EXCEPTION 'Primary key %',t->>'name'; END IF;
FOR x IN SELECT value FROM jsonb_array_elements(t->'foreign_keys') LOOP
IF NOT EXISTS (SELECT 1 FROM pg_constraint f WHERE f.conrelid=rel AND f.conname=x->>'name' AND f.contype='f' AND f.confrelid=to_regclass(format('%I.%I','WEBFUSION',x->>'table')) AND f.confdeltype=CASE WHEN x->>'delete'='CASCADE' THEN 'c'::"char" ELSE 'a'::"char" END AND f.confupdtype='a' AND f.convalidated AND to_jsonb(ARRAY(SELECT at.attname::text FROM unnest(f.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute at ON at.attrelid=rel AND at.attnum=k.num ORDER BY k.ord))=x->'columns' AND to_jsonb(ARRAY(SELECT at.attname::text FROM unnest(f.confkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute at ON at.attrelid=f.confrelid AND at.attnum=k.num ORDER BY k.ord))=x->'references') THEN RAISE EXCEPTION 'Foreign key %.%',t->>'name',x->>'name'; END IF; END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(t->'unique') LOOP
IF x->>'mechanism'='host_guard' THEN IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='b10_identity' AND tgenabled='O' AND tgtype=31 AND tgfoid='rffusion_support.file_identity()'::regprocedure AND tgnargs=1 AND tgargs=convert_to(t->'primary_key'->>0,'UTF8')||decode('00','hex')) THEN RAISE EXCEPTION 'Identity guard binding %',t->>'name'; END IF; ELSE IF NOT EXISTS (SELECT 1 FROM pg_constraint u JOIN pg_index i ON i.indexrelid=u.conindid WHERE u.conrelid=rel AND u.conname=x->>'physical' AND u.contype='u' AND NOT i.indnullsnotdistinct AND to_jsonb(ARRAY(SELECT at.attname::text FROM unnest(u.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute at ON at.attrelid=rel AND at.attnum=k.num ORDER BY k.ord))=(SELECT jsonb_agg(m->'column') FROM jsonb_array_elements(x->'members') m)) THEN RAISE EXCEPTION 'Unique %.%',t->>'name',x->>'name'; END IF; END IF; END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(t->'indexes') LOOP
IF NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_am am ON am.oid=ic.relam WHERE i.indrelid=rel AND ic.relname=x->>'physical' AND am.amname=x->>'kind' AND i.indisvalid AND i.indisready AND NOT i.indisunique AND regexp_replace(lower(substring(pg_get_indexdef(i.indexrelid) FROM 'USING [^ ]+ (.*)$')), '(::text|::regconfig|::character varying|[[:space:]"()])', '', 'g') =regexp_replace(lower(x->>'expression'), '(::text|::regconfig|::character varying|[[:space:]"()])', '', 'g')) THEN RAISE EXCEPTION 'Index %.%',t->>'name',x->>'name'; END IF; END LOOP;
END LOOP;
IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='WEBFUSION' AND c.relkind='r')<>2 THEN RAISE EXCEPTION 'Unexpected business tables'; END IF;
END;
$verify$;
\ir verifyTechnical.sql
COMMIT;
\echo verified WEBFUSION
